if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_adddevicetobond() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    case "${#ref[@]}" in
    1) _helper_devices ;;
    2) _helper_bonds ;;
    esac
}

_choice_addpreferredwirelessnetworkatindex() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    case "${#ref[@]}" in
    1) _helper_devices ;;
    2) _helper_preferredwirelessnets "${ref[0]}" ;;
    4) printf '%s\n' OPEN WPA WPAE WPA2 WPA2E WEP 8021XWEP ;;
    esac
}

_choice_bond() {
    _helper_bonds
}

_choice_device() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    local slot=${#ref[@]}
    case "${argc__option}" in
    argc_createVLAN | argc_deleteVLAN)
        [[ $slot -eq 2 ]] && _helper_devices
        ;;
    argc_createBond)
        [[ $slot -ge 2 ]] && _helper_devices
        ;;
    argc_setairportpower)
        case $slot in
        1) _helper_devices ;;
        2) printf '%s\n' on off ;;
        esac
        ;;
    argc_getairportnetwork | argc_getairportpower | argc_listpreferredwirelessnetworks | argc_removeallpreferredwirelessnetworks | argc_isBondSupported | argc_createpppoeservice)
        [[ $slot -eq 1 ]] && _helper_devices
        ;;
    esac
}

_choice_hardwareport() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    case "${argc__option}:${#ref[@]}" in
    argc_createnetworkservice:2 | argc_getmacaddress:1 | argc_setMTUAndMediaAutomatically:1 | argc_getMTU:1 | argc_setMTU:1 | argc_listvalidMTUrange:1 | argc_getmedia:1 | argc_listvalidmedia:1)
        _helper_hardwareports
        ;;
    esac
}

_choice_location() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    case "${argc__option}:${#ref[@]}" in
    argc_createlocation:1 | argc_deletelocation:1 | argc_switchtolocation:1) _helper_locations ;;
    argc_createlocation:2) printf '%s\n' populate ;;
    esac
}

_choice_networkservice() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    local slot=${#ref[@]}
    case "${argc__option}" in
    argc_ordernetworkservices)
        _helper_networkservices
        ;;
    argc_setwebproxystate | argc_setsecurewebproxystate | argc_setsocksfirewallproxystate | argc_setproxyautodiscovery | argc_setautoproxystate | argc_setnetworkserviceenabled)
        case $slot in
        1) _helper_networkservices ;;
        *) printf '%s\n' on off ;;
        esac
        ;;
    argc_setwebproxy | argc_setsecurewebproxy | argc_setsocksfirewallproxy)
        case $slot in
        1) _helper_networkservices ;;
        4) printf '%s\n' on off ;;
        esac
        ;;
    *)
        [[ $slot -eq 1 ]] && _helper_networkservices
        ;;
    esac
}

_choice_pppoeservice() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    case "${argc__option}:${#ref[@]}" in
    argc_showpppoestatus:1 | argc_deletepppoeservice:1 | argc_setpppoeaccountname:1 | argc_setpppoepassword:1 | argc_connectpppoeservice:1 | argc_disconnectpppoeservice:1)
        _helper_pppoeservices
        ;;
    esac
}

_choice_removedevicefrombond() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    case "${#ref[@]}" in
    1) _helper_devices ;;
    2) _helper_bonds ;;
    esac
}

_choice_removepreferredwirelessnetwork() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    case "${#ref[@]}" in
    1) _helper_devices ;;
    2) _helper_preferredwirelessnets "${ref[0]}" ;;
    esac
}

_choice_setairportnetwork() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    case "${#ref[@]}" in
    1) _helper_devices ;;
    2) _helper_preferredwirelessnets "${ref[0]}" ;;
    esac
}

_choice_setmedia() {
    [[ -n "${argc__option:-}" ]] || return 0
    local -n ref="${argc__option}"
    case "${#ref[@]}" in
    1) _helper_hardwareports ;;
    2) _helper_validmedia "${ref[0]}" | gawk '{ print $1 }' ;;
    *) _helper_mediaoptions "${ref[0]}" "${ref[1]}" ;;
    esac
}

_helper_bonds() {
    networksetup -listBonds 2>/dev/null
}

_helper_devices() {
    networksetup -listallhardwareports 2>/dev/null | gawk -F': ' '/^Device: / { print $2 }'
}

_helper_hardwareports() {
    networksetup -listallhardwareports 2>/dev/null | gawk '
    /^Hardware Port: / { port = substr($0, 16); print port; next }
    /^Device: / { print $2 "\t" port }
    '
}

_helper_locations() {
    networksetup -listlocations 2>/dev/null
}

_helper_mediaoptions() {
    [[ -n "${1:-}" && -n "${2:-}" ]] || return 0
    _helper_validmedia "$1" | gawk -v subtype="$2" '
    $1 == subtype && /</ {
        line = $0
        sub(/^[^<]*</, "", line)
        sub(/>.*$/, "", line)
        n = split(line, parts, /, */)
        for (i = 1; i <= n; i++) print parts[i]
    }
    '
}

_helper_networkservices() {
    networksetup -listallnetworkservices 2>/dev/null | sed -e '1d' -e 's/^\*//'
}

_helper_pppoeservices() {
    networksetup -listpppoeservices 2>/dev/null
}

_helper_preferredwirelessnets() {
    [[ -n "${1:-}" ]] || return 0
    networksetup -listpreferredwirelessnetworks "$1" 2>/dev/null | sed -e '1d' -e 's/^\t//'
}

_helper_validmedia() {
    [[ -n "${1:-}" ]] || return 0
    networksetup -listvalidmedia "$1" 2>/dev/null
}
